// notification-queue.module.ts
import { Module } from '@nestjs/common';
import { BullModule } from '@nestjs/bullmq';
import { NotificationService } from './notification.service';
import { NotificationProcessor } from './notification.processor';
import { PrimaryEmailProvider } from './providers/primary-email.provider';
import { FallbackEmailProvider } from './providers/fallback-email.provider';

@Module({
  imports: [
    BullModule.registerQueue({
      name: 'notifications',
      defaultJobOptions: {
        attempts: 5,
        backoff: {
          type: 'exponential',
          delay: 2000, // ms — first retry ~2s, then 4s, 8s, 16s...
        },
      },
    }),
  ],
  providers: [
    NotificationService,
    NotificationProcessor,
    PrimaryEmailProvider,
    FallbackEmailProvider,
  ],
  exports: [NotificationService],
})
export class NotificationQueueModule {}

// notification.service.ts
import { Injectable } from '@nestjs/common';
import { InjectQueue } from '@nestjs/bullmq';
import { Queue } from 'bullmq';

export interface SendNotificationDto {
  channel: 'email';
  to: string;
  templateId: string;
  params: Record<string, string | number>;
}

interface NotificationJobPayload {
  channel: 'email';
  to: string;
  templateId: string;
  params: Record<string, string | number>;
}

@Injectable()
export class NotificationService {
  constructor(@InjectQueue('notifications') private readonly queue: Queue) {}

  /**
   * Enqueues a transactional notification (e.g. login OTP email) for
   * async delivery by NotificationProcessor.
   */
  async enqueue(dto: SendNotificationDto): Promise<void> {
    const payload: NotificationJobPayload = {
      channel: dto.channel,
      to: dto.to,
      templateId: dto.templateId,
      params: dto.params,
    };

    // NOTE: no messageId / idempotencyKey is stamped here — the job carries
    // nothing that lets a later redelivery be told apart from the original.
    await this.queue.add('send-notification', payload);
  }
}

// notification.processor.ts
import { Logger } from '@nestjs/common';
import { Processor, WorkerHost } from '@nestjs/bullmq';
import { Job } from 'bullmq';
import { PrimaryEmailProvider } from './providers/primary-email.provider';
import { FallbackEmailProvider } from './providers/fallback-email.provider';

interface NotificationJobPayload {
  channel: 'email';
  to: string;
  templateId: string;
  params: Record<string, string | number>;
}

@Processor('notifications')
export class NotificationProcessor extends WorkerHost {
  private readonly logger = new Logger(NotificationProcessor.name);

  constructor(
    private readonly primaryProvider: PrimaryEmailProvider,
    // Injected per the "we fail over to the backup provider" PR description,
    // but process() below never actually calls it.
    private readonly fallbackProvider: FallbackEmailProvider,
  ) {
    super();
  }

  async process(job: Job<NotificationJobPayload>): Promise<void> {
    const { channel, to, templateId, params } = job.data;

    try {
      await this.primaryProvider.send(channel, to, templateId, params);
    } catch (err) {
      this.logger.error(err);
      // "Failover" per the PR: just rethrow and let BullMQ's attempts +
      // exponential backoff (see notification-queue.module.ts) retry the job.
      // On the next attempt this.primaryProvider is called again — the
      // fallbackProvider above is never invoked anywhere in this class.
      throw err;
    }
  }
}

